Here are a few ways to write a JavaScript function that capitalizes the first letter of each word in a sentence, ranging from a simple approach to a more robust one.

### Method 1: Using `split()`, `map()`, and `join()` (Recommended for Simplicity)

This is often the most idiomatic and readable way in JavaScript.

```javascript
/**
 * Capitalizes the first letter of each word in a sentence.
 * @param {string} sentence The input string.
 * @returns {string} The sentence with each word capitalized.
 */
function capitalizeWords(sentence) {
  if (!sentence || typeof sentence !== 'string') {
    return "";
  }

  // 1. Convert the entire string to lowercase first to handle mixed-case input consistently.
  // 2. Split the string into an array of words using spaces as the delimiter.
  const words = sentence.toLowerCase().split(' ');

  // 3. Map over the array, capitalizing the first letter of each word.
  const capitalizedWords = words.map(word => {
    if (word.length === 0) {
      return ''; // Handle multiple spaces resulting in empty strings
    }
    // Capitalize the first letter and concatenate the rest of the word.
    return word.charAt(0).toUpperCase() + word.slice(1);
  });

  // 4. Join the array back into a single string with spaces.
  return capitalizedWords.join(' ');
}

// --- Examples ---
console.log(capitalizeWords("hello world, this is a test")); // Output: Hello World, This Is A Test
console.log(capitalizeWords("a quick brown fox"));          // Output: A Quick Brown Fox
console.log(capitalizeWords("already Capitalized"));        // Output: Already Capitalized
console.log(capitalizeWords("  leading and trailing spaces ")); // Output:   Leading And Trailing Spaces
